import math
def control(obs):
    h=obs['hitch_deg']
    cam=obs.get('views',{}).get('camera')
    steer=2.3*h
    if cam and cam.get('walls'):
        sides=[[],[]]
        for b,d in cam['walls']:
            a=math.radians(b+h)
            u=-d*math.cos(a); y=d*math.sin(a)
            if u>0.3:
                sides[0 if y<0 else 1].append((u,y))
        def interp(points,u):
            points.sort()
            for p,q in zip(points,points[1:]):
                if p[0]<=u<=q[0] and q[0]-p[0]>0.01:
                    return p[1]+(q[1]-p[1])*(u-p[0])/(q[0]-p[0])
            return min(points,key=lambda p:abs(p[0]-u))[1]
        if all(sides):
            u=3.5
            y=(interp(sides[0],u)+interp(sides[1],u))/2
            k=2*y/(u*u+y*y)
            desired=math.degrees(math.asin(max(-0.58,min(0.58,3.65*k))))
            steer=0.75*h+1.6*(h-desired)
    return (max(-34,min(34,steer)),-0.65,-23)

