            return min(points,key=lambda p:abs(p[0]-u))[1]
        u=3.5; y=None
        if all(sides): y=(interp(sides[0],u)+interp(sides[1],u))/2
        pts=[]
        for b,d in cam.get('target_corners',[]):
            a=math.radians(b+h); pts.append((-d*math.cos(a),d*math.sin(a)))
        if len(pts)>=4:
            pts.sort(); near=pts[:2]; far=pts[-2:]
