 h=o['hitch_deg']; th=math.radians(-h)
 cam=o['views'].get('camera')
 desired=0.0
 if cam:
  sides=[[],[]]
  for b,d in cam.get('walls',[]):
   a=math.radians(b); x=d*math.cos(a); y=d*math.sin(a)
   u=-x*math.cos(th)-y*math.sin(th); l=-x*math.sin(th)+y*math.cos(th)
   if 1.5<u<14 and abs(l)>1:
    sides[0 if l>0 else 1].append((u,l))
  fits=[]
  for ps in sides:
   if len(ps)>=3:
    n=len(ps); mx=sum(p[0] for p in ps)/n; my=sum(p[1] for p in ps)/n
    den=sum((p[0]-mx)**2 for p in ps)
    k=sum((p[0]-mx)*(p[1]-my) for p in ps)/max(.1,den)
    fits.append((my-k*mx,k))
  if len(fits)==2:
   c=(fits[0][0]+fits[1][0])/2; k=(fits[0][1]+fits[1][1])/2
   desired=math.degrees(math.atan(k+c/9))
   desired=max(-30,min(30,desired))
  if o['t']-last>12:
   print('camera fit',fits,'desired',round(desired,1),'hitch',round(h,1),'remaining',round(o['progress']['remaining'],1)); last=o['t']
 steer=max(-42,min(42,2.0*(h-desired)+.38*h))
 return (steer,-.9,-41)
